mapper.select:
SELECT RECORD_ID AS "recordId", RULE_ID AS "ruleId", INVENTORY_ID AS "inventoryId", INVENTORY_CODE AS "inventoryCode", INVENTORY_NAME AS "inventoryName", WAREHOUSE_ID AS "warehouseId", WAREHOUSE_NAME AS "warehouseName", ALERT_TYPE AS "alertType", ALERT_TYPE_NAME AS "alertTypeName", ALERT_LEVEL AS "alertLevel", CURRENT_QUANTITY AS "currentQuantity", ALERT_VALUE AS "alertValue", ALERT_MESSAGE AS "alertMessage", CASE PROCESS_STATUS WHEN 0 THEN 'PENDING' WHEN 1 THEN 'PROCESSING' WHEN 2 THEN 'PROCESSED' WHEN 3 THEN 'IGNORED' ELSE 'UNKNOWN' END AS "status", PROCESSOR_ID AS "processorId", PROCESSOR_NAME AS "processorName", TO_CHAR(PROCESS_TIME, 'YYYY-MM-DD HH24:MI:SS') AS "processTime", PROCESS_REMARK AS "processRemark", TO_CHAR(CREATE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS "alertTime" FROM TBL_INVENTORY_ALERT_RECORD WHERE 1=1
AND TENANT_ID = #{param.tenantId}
AND ALERT_TYPE = #{param.alertType}
AND ALERT_LEVEL = #{param.alertLevel}
AND PROCESS_STATUS = CASE #{param.status} WHEN 'PENDING' THEN 0 WHEN 'PROCESSING' THEN 1 WHEN 'PROCESSED' THEN 2 WHEN 'IGNORED' THEN 3 ELSE -1 END
AND INVENTORY_NAME LIKE '%' || #{param.inventoryName} || '%'
AND WAREHOUSE_ID = #{param.warehouseId}
AND CREATE_TIME >= TO_DATE(#{param.startDate}, 'YYYY-MM-DD')
AND CREATE_TIME <= TO_DATE(#{param.endDate}, 'YYYY-MM-DD') + 1
ORDER BY CREATE_TIME DESC

SELECT ALERT_TYPE AS "alertType", ALERT_TYPE_NAME AS "alertTypeName", COUNT(*) AS "count", ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM TBL_INVENTORY_ALERT_RECORD WHERE TENANT_ID = #{param.tenantId}), 2) AS "percentage" FROM TBL_INVENTORY_ALERT_RECORD WHERE 1=1
AND TENANT_ID = #{param.tenantId}
GROUP BY ALERT_TYPE, ALERT_TYPE_NAME ORDER BY COUNT(*) DESC
